// =================================================================
// control_unit.v  ?  FSM Control Unit?16x16 ??
// =================================================================
module control_unit (
    input        clk,
    input        rst,
    output reg [7:0] pc,
    input      [15:0] instr,
    output reg [3:0] alu_op,
    output reg [7:0] alu_op1,
    output reg [7:0] alu_op2,
    input      [7:0] alu_result,
    input            alu_flagZ,
    output reg [1:0] rf_rd_addrA,
    output reg [1:0] rf_rd_addrB,
    input      [7:0] rf_dataA,
    input      [7:0] rf_dataB,
    output reg       rf_wr_en,
    output reg [1:0] rf_wr_addr,
    output reg [7:0] rf_wr_data,
    output reg       vram_wr_req,
    input            vram_wr_gnt,
    output reg [7:0] vram_addr,
    output reg [2:0] vram_data,
    output reg [3:0] cur_opcode,
    output reg [1:0] cur_state
);
    localparam [1:0] S_FETCH=2'b00, S_DECODE=2'b01, S_EXECUTE=2'b10, S_WRITEBACK=2'b11;
    localparam [3:0]
        OP_MOV=4'b0000, OP_ADD=4'b0001, OP_SUB=4'b0010,
        OP_AND=4'b0011, OP_OR =4'b0100, OP_OUT=4'b0101,
        OP_BEQ=4'b0110, OP_JMP=4'b0111;
    reg [15:0] IR;
    wire [3:0] ir_opcode = IR[15:12];
    wire [1:0] ir_rd     = IR[11:10];
    wire [1:0] ir_rs     = IR[9:8];
    wire [7:0] ir_imm8   = IR[7:0];
    reg [1:0] state;
    always @(posedge clk) begin
        if (rst) begin
            state <= S_FETCH; pc <= 8'h00;
            IR <= 16'h0000; rf_wr_en <= 0; vram_wr_req <= 0;
        end else begin
            cur_state <= state;
            case (state)
                S_FETCH: begin
                    IR <= instr; rf_wr_en <= 0; vram_wr_req <= 0;
                    state <= S_DECODE;
                end
                S_DECODE: begin
                    cur_opcode  <= ir_opcode;
                    rf_rd_addrA <= ir_rd;
                    rf_rd_addrB <= ir_rs;
                    alu_op      <= ir_opcode;
                    state       <= S_EXECUTE;
                end
                S_EXECUTE: begin
                    alu_op1 <= rf_dataA;
                    alu_op2 <= (ir_opcode==OP_MOV||ir_opcode==OP_BEQ||ir_opcode==OP_JMP)
                               ? ir_imm8 : rf_dataB;
                    if (ir_opcode == OP_OUT) begin
                        vram_addr   <= ir_imm8;
                        vram_data   <= rf_dataB[2:0];
                        vram_wr_req <= 1;
                    end
                    state <= S_WRITEBACK;
                end
                S_WRITEBACK: begin
                    vram_wr_req <= 0;
                    case (ir_opcode)
                        OP_MOV, OP_ADD, OP_SUB, OP_AND, OP_OR: begin
                            rf_wr_en <= 1; rf_wr_addr <= ir_rd;
                            rf_wr_data <= alu_result; pc <= pc + 8'h01;
                        end
                        OP_OUT: begin
                            rf_wr_en <= 0;
                            if (vram_wr_gnt) pc <= pc + 8'h01;
                            else begin vram_wr_req <= 1; state <= S_WRITEBACK; end
                        end
                        OP_BEQ: begin
                            rf_wr_en <= 0;
                            pc <= alu_flagZ ? ir_imm8 : (pc + 8'h01);
                        end
                        OP_JMP: begin rf_wr_en <= 0; pc <= ir_imm8; end
                        default: begin rf_wr_en <= 0; pc <= pc + 8'h01; end
                    endcase
                    if (ir_opcode != OP_OUT || vram_wr_gnt) state <= S_FETCH;
                end
            endcase
        end
    end
endmodule
// =================================================================
// alu.v  ?  8-bit ALU for Dual-Core CPU
//
// ISA opcodes (4-bit):
//   0000  MOV  : Result = Operand2 (immediate passthrough)
//   0001  ADD  : Result = Op1 + Op2
//   0010  SUB  : Result = Op1 - Op2
//   0011  AND  : Result = Op1 & Op2
//   0100  OR   : Result = Op1 | Op2
//   0101  OUT  : Result = Op2 (pixel color passthrough ? VRAM)
//   0110  BEQ  : Result = Op1 (branch???control unit?flagZ)
//   0111  JMP  : Result = Op2 (target addr passthrough)
//
// flagZ : Result == 0  (BEQ ?)
// flagC : carry out    (?????????)
// =================================================================

module alu (
    input  [3:0] opcode,
    input  [7:0] operand1,   // Rs (source register value)
    input  [7:0] operand2,   // Rd or immediate
    output reg [7:0] result,
    output reg flagZ,
    output reg flagC
);

    // ----------------------------------------------------------
    // Opcode parameters (? control_unit.v ?????????
    // `include "isa_def.vh"????? localparam ????)
    // ----------------------------------------------------------
    localparam [3:0]
        OP_MOV = 4'b0000,
        OP_ADD = 4'b0001,
        OP_SUB = 4'b0010,
        OP_AND = 4'b0011,
        OP_OR  = 4'b0100,
        OP_OUT = 4'b0101,   // ????? operand2 (??) ????
        OP_BEQ = 4'b0110,   // branch if zero?ALU ?? pass?PC ? CU ??
        OP_JMP = 4'b0111;   // jump?ALU pass target?CU ??

    // ----------------------------------------------------------
    // 9-bit ???[8] ? carry?[7:0] ???
    // ???????????????????
    // ----------------------------------------------------------
    reg [8:0] tmp;

    always @(*) begin
        // ?????? latch?
        tmp   = 9'b0;
        flagC = 1'b0;
        flagZ = 1'b0;

        case (opcode)

            // --------------------------------------------------
            // MOV Rd, imm  ?  Rd ? imm?operand2 ? immediate?
            // --------------------------------------------------
            OP_MOV: begin
                tmp   = {1'b0, operand2};
                flagC = 1'b0;
            end

            // --------------------------------------------------
            // ADD Rd, Rs  ?  Rd ? Rd + Rs
            // --------------------------------------------------
            OP_ADD: begin
                tmp   = {1'b0, operand1} + {1'b0, operand2};
                flagC = tmp[8];              // ??????bit[8] ? carry
            end

            // --------------------------------------------------
            // SUB Rd, Rs  ?  Rd ? Rd - Rs
            // --------------------------------------------------
            OP_SUB: begin
                tmp   = {1'b0, operand1} - {1'b0, operand2};
                flagC = tmp[8];              // borrow flag???? SUB ???
            end

            // --------------------------------------------------
            // AND Rd, Rs  ?  Rd ? Rd & Rs
            // --------------------------------------------------
            OP_AND: begin
                tmp   = {1'b0, operand1 & operand2};
                flagC = 1'b0;               // ??????? carry?????
            end

            // --------------------------------------------------
            // OR Rd, Rs  ?  Rd ? Rd | Rs
            // --------------------------------------------------
            OP_OR: begin
                tmp   = {1'b0, operand1 | operand2};
                flagC = 1'b0;
            end

            // --------------------------------------------------
            // OUT addr, Rs  ?  ? Rs ? RGB ????pass-through?
            // ALU ???? operand1?Rs ?????????
            // control_unit ??? result ?? VRAM
            // --------------------------------------------------
            OP_OUT: begin
                tmp   = {1'b0, operand1};   // operand1 = Rs (pixel color)
                flagC = 1'b0;
            end

            // --------------------------------------------------
            // BEQ Rs, imm  ?  if Rs == 0: PC ? imm
            // ALU ?? Rs ??? CU ?? flagZ?
            // target address ???? immediate ????
            // --------------------------------------------------
            OP_BEQ: begin
                tmp   = {1'b0, operand1};   // operand1 = Rs?? flagZ ????? 0?
                flagC = 1'b0;
            end

            // --------------------------------------------------
            // JMP imm  ?  PC ? imm???????
            // ALU ?? target?operand2??CU ???? PC
            // --------------------------------------------------
            OP_JMP: begin
                tmp   = {1'b0, operand2};   // operand2 = immediate target
                flagC = 1'b0;
            end

            // --------------------------------------------------
            // Default??? 0?????
            // --------------------------------------------------
            default: begin
                tmp   = 9'b0;
                flagC = 1'b0;
            end

        endcase

        // flagZ?result[7:0] ?? 0 ????????????? 8-bit ???
        result = tmp[7:0];
        flagZ  = (result == 8'h00);
    end

endmodule

module core0 (
  input clk_global,
  input reset_global,
  input vram_wr_gnt,
  input [1:0] image_sel,
  output vram_req,
  output [7:0] vram_addr,
  output [2:0] vram_data
);
  wire [3:0] s0;
  wire [7:0] s1;
  wire [7:0] s2;
  wire [7:0] result;
  wire fz;
  wire s3;
  wire [1:0] s4;
  wire [7:0] s5;
  wire [1:0] s6;
  wire [1:0] s7;
  wire [7:0] s8;
  wire [7:0] s9;
  wire [7:0] s10;
  wire [15:0] instr;
  // reg_file
  reg_file reg_file_i0 (
    .clk( clk_global ),
    .rst( reset_global ),
    .wr_en( s3 ),
    .wr_addr( s4 ),
    .wr_data( s5 ),
    .rd_addrA( s6 ),
    .rd_addrB( s7 ),
    .rd_dataA( s8 ),
    .rd_dataB( s9 )
  );
  // prog_rom_c0
  prog_rom_c0 prog_rom_c0_i1 (
    .pc( s10 ),
    .img_sel( image_sel ),
    .instr( instr )
  );
  // control_unit
  control_unit control_unit_i2 (
    .clk( clk_global ),
    .rst( reset_global ),
    .instr( instr ),
    .alu_result( result ),
    .alu_flagZ( fz ),
    .rf_dataA( s8 ),
    .rf_dataB( s9 ),
    .vram_wr_gnt( vram_wr_gnt ),
    .pc( s10 ),
    .alu_op( s0 ),
    .alu_op1( s1 ),
    .alu_op2( s2 ),
    .rf_rd_addrA( s6 ),
    .rf_rd_addrB( s7 ),
    .rf_wr_en( s3 ),
    .rf_wr_addr( s4 ),
    .rf_wr_data( s5 ),
    .vram_wr_req( vram_req ),
    .vram_addr( vram_addr ),
    .vram_data( vram_data )
  );
  // alu
  alu alu_i3 (
    .opcode( s0 ),
    .operand1( s1 ),
    .operand2( s2 ),
    .result( result ),
    .flagZ( fz )
  );
endmodule
