// =================================================================
// bus_arbiter.v  ?  Round-Robin Bus Arbiter
//
// ?? core ?? VRAM ???
// ???round-robin??????????????
// gnt ?? req ?????????????
// =================================================================

module bus_arbiter (
    input  clk,
    input  rst,

    // Core 0
    input  req0,
    output reg gnt0,

    // Core 1
    input  req1,
    output reg gnt1
);

    reg last_gnt;   // 0 = ??? core0?1 = ??? core1

    always @(posedge clk) begin
        if (rst) begin
            gnt0     <= 1'b0;
            gnt1     <= 1'b0;
            last_gnt <= 1'b0;
        end else begin
            gnt0 <= 1'b0;
            gnt1 <= 1'b0;

            if (req0 && req1) begin
                // ?????? ? ??
                if (last_gnt == 1'b0) begin
                    gnt1     <= 1'b1;
                    last_gnt <= 1'b1;
                end else begin
                    gnt0     <= 1'b1;
                    last_gnt <= 1'b0;
                end
            end else if (req0) begin
                gnt0     <= 1'b1;
                last_gnt <= 1'b0;
            end else if (req1) begin
                gnt1     <= 1'b1;
                last_gnt <= 1'b1;
            end
        end
    end

endmodule
// =================================================================
// pixel_driver.v  ?  VGA 640×480 ??16×16 VRAM ?????
//
// 16×16 VRAM ??? 640×480?
//   ??????? 40×30 ? VGA ??
//   hcount / 40 = vram_x (0~15)
//   vcount / 30 = vram_y (0~15)
//   vram_addr   = vram_y * 16 + vram_x (0~255)
// =================================================================
module pixel_driver (
    input        clk,
    input        rst,
    // ?? vga_sync?640×480?
    input  [9:0] hcount,
    input  [9:0] vcount,
    input        video_on,
    // VRAM ????
    output [7:0] vram_rd_addr,
    input  [2:0] vram_rd_data,   // [2]=R [1]=G [0]=B
    // VGA RGB ???1-bit each?
    output R,
    output G,
    output B
);
    // ??????????????????????
    // hcount 0~639  / 40 ? 0~15
    // vcount 0~479  / 30 ? 0~15
    reg [3:0] hmap [0:639];
    reg [3:0] vmap [0:479];
    integer i;
    initial begin
        for (i = 0; i < 640; i = i + 1)
            hmap[i] = i / 40;
        for (i = 0; i < 480; i = i + 1)
            vmap[i] = i / 30;
    end

    wire [3:0] px = hmap[hcount];
    wire [3:0] py = vmap[vcount];

    // VRAM ?? = py * 16 + px
    assign vram_rd_addr = {py, px};

    // RGB ??
    assign R = video_on ? vram_rd_data[2] : 1'b0;
    assign G = video_on ? vram_rd_data[1] : 1'b0;
    assign B = video_on ? vram_rd_data[0] : 1'b0;
endmodule
// =================================================================
// vram.v  ?  Shared VRAM  256 × 3-bit?16×16 ???
//
// addr 0~127   ? Core 0?row 0~7?
// addr 128~255 ? Core 1?row 8~15?
// =================================================================

module vram (
    input        clk,
    input        wr_en0,
    input  [7:0] wr_addr0,
    input  [2:0] wr_data0,
    input        wr_en1,
    input  [7:0] wr_addr1,
    input  [2:0] wr_data1,
    input  [7:0] rd_addr,
    output [2:0] rd_data
);
    reg [2:0] mem [0:255];

    always @(posedge clk) begin
        if (wr_en0) mem[wr_addr0] <= wr_data0;
        if (wr_en1) mem[wr_addr1] <= wr_data1;
    end

    assign rd_data = mem[rd_addr];
endmodule

